export class JobQueue {
  private concurrency: number;
  private retries: number;
  private pending: (() => Promise<void>)[] = [];
  private active = 0;
  private idleWaiters: (() => void)[] = [];

  constructor(concurrency: number, retries = 3) {
    if (!Number.isInteger(concurrency) || concurrency < 1) {
      throw new RangeError("concurrency must be an integer >= 1");
    }
    this.concurrency = concurrency;
    this.retries = retries;
  }

  /** Resolves with the job's result, or rejects with its last error once retries are exhausted. */
  add<T>(job: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.pending.push(() => this.attempt(job).then(resolve, reject));
      this.next();
    });
  }

  /** Resolves when nothing is running or waiting. Never rejects; job errors surface via add(). */
  onIdle(): Promise<void> {
    if (!this.active && !this.pending.length) return Promise.resolve();
    return new Promise((resolve) => this.idleWaiters.push(resolve));
  }

  private next(): void {
    while (this.active < this.concurrency && this.pending.length) {
      this.active++;
      this.pending.shift()!().finally(() => {
        this.active--;
        this.next();
      });
    }
    if (!this.active) for (const resolve of this.idleWaiters.splice(0)) resolve();
  }

  // Retries immediately and keeps the concurrency slot while doing so.
  private async attempt<T>(job: () => Promise<T>): Promise<T> {
    for (let failures = 0; ; failures++) {
      try {
        return await job();
      } catch (err) {
        if (failures >= this.retries) throw err;
      }
    }
  }
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { JobQueue } from "./queue.ts";

const tick = () => new Promise((r) => setTimeout(r, 5));

test("respects concurrency limit and onIdle waits for everything", async () => {
  const q = new JobQueue(2);
  let running = 0, peak = 0, done = 0;
  for (let i = 0; i < 6; i++) {
    q.add(async () => {
      peak = Math.max(peak, ++running);
      await tick();
      running--;
      done++;
    });
  }
  await q.onIdle();
  assert.equal(peak, 2);
  assert.equal(done, 6);
});

test("retries up to three times, then rejects", async () => {
  const q = new JobQueue(1);
  let flaky = 0, dead = 0;
  const ok = q.add(async () => {
    if (++flaky < 4) throw new Error("flaky");
    return "ok";
  });
  const bad = q.add(async () => {
    dead++;
    throw new Error("dead");
  });
  await assert.rejects(bad, /dead/);
  assert.equal(await ok, "ok");
  assert.equal(flaky, 4);
  assert.equal(dead, 4);
  await q.onIdle();
});

